<?php defined('ALTUMCODE') || die();$nextEvents=fcc_event_list((int)$this->user->user_id);$nextEvent=null;foreach($nextEvents as $candidate)if($candidate['status']==='scheduled'){$nextEvent=$candidate;break;} ?>
<section class="fp-panel" style="margin-bottom:20px"><span class="fp-eyebrow"><?= htmlspecialchars(fcc_t('SLJEDEĆI DOGAĐAJ ZA TEBE'), ENT_QUOTES, 'UTF-8') ?></span><?php if($nextEvent): ?><h2><?= fcc_partner_h($nextEvent['title']) ?></h2><p><?= fcc_partner_h(fcc_event_label($nextEvent)) ?></p><?php /* Custom code: FC-2026-10-11: One-click attendance on Today; reminders go only to confirmed attendees. */ $nextGoing=function_exists('fcc_event_rsvp')&&(fcc_event_rsvp((int)$this->user->user_id,(int)$nextEvent['id'])['state']??'')==='going'; ?><div class="fp-actions"><?php if($nextGoing): ?><span class="fp-muted"><?= htmlspecialchars(fcc_t('Dolazak je potvrđen. Podsjetnik stiže prije početka.'), ENT_QUOTES, 'UTF-8') ?></span><?php elseif(function_exists('fcc_event_rsvp_ready')&&fcc_event_rsvp_ready()&&fcc_event_rsvp_open($nextEvent)): ?><form method="post" action="<?= url('partner/webinars/'.(int)$nextEvent['id']) ?>"><input type="hidden" name="token" value="<?= fcc_partner_h(\Altum\Csrf::get()) ?>"><input type="hidden" name="action" value="rsvp"><input type="hidden" name="revision" value="<?= (int)$nextEvent['revision'] ?>"><input type="hidden" name="rsvp" value="going"><button class="fp-button"><?= htmlspecialchars(fcc_t('Dolazim'), ENT_QUOTES, 'UTF-8') ?></button></form><?php endif ?><a class="fp-button fp-button-outline" href="<?= url('partner/webinars/'.$nextEvent['id']) ?>"><?= htmlspecialchars(fcc_t('Otvori termin'), ENT_QUOTES, 'UTF-8') ?></a></div><?php if(!$nextGoing): ?><p class="fp-muted"><?= htmlspecialchars(fcc_t('Podsjetnik prije događaja dobivaš kada potvrdiš dolazak.'), ENT_QUOTES, 'UTF-8') ?></p><?php endif ?><?php /* /Custom code: FC-2026-10-11 */ ?><?php else: ?><p><?= htmlspecialchars(fcc_t('Sljedeći termin još nije objavljen.'), ENT_QUOTES, 'UTF-8') ?></p><?php endif ?> <a class="fp-link" href="<?= url('partner/webinars') ?>"><?= htmlspecialchars(fcc_t('Svi webinari i događaji →'), ENT_QUOTES, 'UTF-8') ?></a></section>
